mapper.select:
SELECT lr.id, lr.loss_no AS lossNo, lr.goods_id AS goodsId, g.name AS goodsName, lr.batch_id AS batchId, lr.batch_no AS batchNo, lr.loss_count AS lossCount, lr.loss_type AS lossType, lr.purchase_price AS purchasePrice, lr.loss_amount AS lossAmount, lr.reason, lr.status, lr.reporter_id AS reporterId, u1.name AS reporterName, lr.auditor_id AS auditorId, u2.name AS auditorName, lr.create_time AS createTime, lr.audit_time AS auditTime FROM loss_report lr LEFT JOIN goods g ON lr.goods_id = g.id LEFT JOIN user u1 ON lr.reporter_id = u1.id LEFT JOIN user u2 ON lr.auditor_id = u2.id
AND lr.loss_no LIKE CONCAT('%', #{lossNo}, '%')
AND lr.status = #{status}
AND lr.loss_type = #{lossType}
AND lr.reporter_id = #{reporterId}
ORDER BY lr.create_time DESC, lr.id DESC
